pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        address originalDistributor = address(this);

        address dummyToken = address(0x1234);
        c.addReward(dummyToken);

        address newDistributor = address(0xABCD);
        c.setRewardDistributor(newDistributor);

        assertTrue(c.rewardDistributor() == newDistributor, "rewardDistributor should be the new distributor");
    }
}
